import torch.nn as nn

# 1. Binary Classification (İkili Sınıflandırma)
class BinaryClassifier(nn.Module):
    def __init__(self):
        super().__init__()
        self.layers = nn.Sequential(
            nn.Linear(100, 50),
            nn.ReLU(),           # Hidden: ReLU
            nn.Linear(50, 1),
            nn.Sigmoid()         # Output: Sigmoid [0,1]
        )
    def forward(self, x):
        return self.layers(x)

# 2. Multi-class Classification (Çok Sınıflı)
class MultiClassClassifier(nn.Module):
    def __init__(self, num_classes=10):
        super().__init__()
        self.layers = nn.Sequential(
            nn.Linear(100, 50),
            nn.ReLU(),           # Hidden: ReLU
            nn.Linear(50, num_classes)
            # Softmax genelde loss içinde (CrossEntropyLoss)
        )
    def forward(self, x):
        return self.layers(x)  # Logits

# 3. Regression (Regresyon - Sayı Tahmini)
class Regressor(nn.Module):
    def __init__(self):
        super().__init__()
        self.layers = nn.Sequential(
            nn.Linear(100, 50),
            nn.ReLU(),           # Hidden: ReLU
            nn.Linear(50, 1)
            # Output: No activation (raw number)
        )
    def forward(self, x):
        return self.layers(x)

print("✓ Binary: Sigmoid output")
print("✓ Multi-class: Softmax (in loss)")
print("✓ Regression: No activation")
